(()=>{let frame=null;addEventListener('keydown',e=>{if(e.code!=='Digit2'||e.repeat)return;e.preventDefault();if(frame){frame.remove();frame=null;document.querySelector('#art').style.visibility='';window.dispatchEvent(new Event('portrait-exit'));return}document.querySelector('#video')?.srcObject?.getTracks().forEach(t=>t.stop());window.dispatchEvent(new Event('portrait-enter'));frame=document.createElement('iframe');frame.src='portrait.html?v=thermal-4';frame.style='position:fixed;inset:0;width:100%;height:100%;border:0;z-index:10;background:black';frame.title='Liquid letter portrait';document.body.append(frame);frame.focus()});addEventListener('message',e=>{if(e.source===frame?.contentWindow&&e.data==='switch-mode'){frame.remove();frame=null;window.dispatchEvent(new Event('portrait-exit'))}})})();
